73	
74	@RestController
75	@CrossOrigin(exposedHeaders = "errors, content-type")
76	@RequestMapping("/api")
77	public class OwnerRestControllerV1 implements OwnersApi {
78	
79	    /**
80	     * Dedicated audit logger. A successful owner create emits a single line here carrying the new
81	     * owner's id, customer code, registration date and membership level, so the create side-effect
82	     * can be audited independently of the application log.
83	     */
84	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
85	
86	    private final ClinicService clinicService;
87	
88	    private final OwnerMapper ownerMapper;
89	
90	    private final PetMapper petMapper;
91	
92	    private final VisitMapper visitMapper;
93	
94	    /**
95	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
96	     * and a domain containing at least one dot, with no whitespace in any segment.
97	     */
98	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
99	
100	    /**
101	     * Email domains belonging to disposable/throwaway mail providers. An owner whose email address
102	     * is on this blocklist (compared case-insensitively on the domain, the part after the final
103	     * {@code '@'}) is rejected with a 400 Bad Request.
104	     */
105	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
106	        "mailinator.com",
107	        "tempmail.com",
108	        "guerrillamail.com");
109	
110	    /**
111	     * Required national-number length per E.164 country code. A normalized telephone whose country
112	     * code appears here must carry exactly this many national digits after the code; Australia
113	     * ({@code +61}) requires 9 and the North American Numbering Plan ({@code +1}) requires 10.
114	     * Country codes not listed are only subject to the generic 8-to-15 total-digit rule.
115	     */
116	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTH = Map.of("61", 9, "1", 10);
117	
118	    /**
119	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
120	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
121	     */
122	    private static final int MAX_OWNERS_PER_CITY = 50;
123	
124	    /**
125	     * Maximum number of owners that may be registered on a single day (by registration date). A create
126	     * attempted once this many owners already carry today's registration date is rejected with a
127	     * 429 Too Many Requests.
128	     */
129	    private static final int MAX_OWNERS_PER_DAY = 100;
130	
131	    /**
132	     * Threshold above which a create is flagged with a bulk-signup warning. When more than this many
133	     * owners already carry the new owner's registration date, the created owner is flagged
134	     * ({@code bulkSignupWarning} true); otherwise the flag is false.
135	     */
136	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
137	
138	    /**
139	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
140	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
141	     */
142	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
143	        "ST", "STREET",
144	        "RD", "ROAD",
145	        "AVE", "AVENUE");
146	
147	    /**
148	     * Inclusive 4-digit postcode range permitted per region, keyed by the region derived from the
149	     * owner's city ({@link Owner#getLocality()}): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A
150	     * region not listed (the {@code 'UNKNOWN'} locality of a city with no known region) accepts any
151	     * 4-digit postcode.
152	     */
153	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
154	        "NSW", new int[] {2000, 2099},
155	        "VIC", new int[] {3000, 3099},
156	        "QLD", new int[] {4000, 4099});
157	
158	    /**
159	     * Name of the request header that carries the client-supplied idempotency key for an owner create.
160	     * When a create repeats with a key already seen, the originally created owner is returned with
161	     * {@code 200 OK} instead of a second owner being created.
162	     */
163	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
164	
165	    /**
166	     * Remembers, per idempotency key, the id of the owner created by the first request that carried that
167	     * key, so a later create repeating the same key can return the original owner instead of creating a
168	     * duplicate. The key space is the client-supplied {@code Idempotency-Key} header value.
169	     */
170	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
171	
172	    public OwnerRestControllerV1(ClinicService clinicService,
173	                                 OwnerMapper ownerMapper,
174	                                 PetMapper petMapper,
175	                                 VisitMapper visitMapper) {
176	        this.clinicService = clinicService;
177	        this.ownerMapper = ownerMapper;
178	        this.petMapper = petMapper;
179	        this.visitMapper = visitMapper;
180	    }
181	
182	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
183	    @Override
184	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
185	        Collection<Owner> owners;
186	        if (lastName != null) {
187	            owners = this.clinicService.findOwnerByLastName(lastName);
188	        } else {
189	            owners = this.clinicService.findAllOwners();
190	        }
191	        if (owners.isEmpty()) {
192	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
193	        }
194	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
195	    }
196	
197	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
198	    @Override
199	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
200	        Owner owner = this.clinicService.findOwnerById(ownerId);
201	        if (owner == null) {
202	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
203	        }
204	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
205	    }
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
210	        String idempotencyKey = currentIdempotencyKey();
211	        if (idempotencyKey != null) {
212	            Integer existingId = idempotentCreates.get(idempotencyKey);
213	            if (existingId != null) {
214	                Owner existing = this.clinicService.findOwnerById(existingId);
215	                if (existing != null) {
216	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
217	                }
218	            }
219	        }
220	        validateRequiredFields(ownerFieldsDto);
221	        HttpHeaders headers = new HttpHeaders();
222	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
223	        rejectFutureRegistrationDate(owner.getRegistrationDate());
224	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
225	        owner.setRegistrationDate(registrationDate);
226	        requireDailyCapacity(registrationDate);
227	        requireCityHasCapacity(owner.getCity());
228	        validatePostcode(owner);
229	        applyAddress(owner, ownerFieldsDto);
230	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
231	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
232	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
233	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
234	        requireNoHouseholdDuplicate(owner, declaredHouseholdMember);
235	        requireUniqueIdentity(owner);
236	        flagPossibleDuplicate(owner, declaredHouseholdMember);
237	        owner.setCustomerCode(deduplicateCustomerCode(owner.buildCustomerCode()));
238	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
239	        stampHouseholdSize(owner);
240	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
241	        this.clinicService.saveOwner(owner);
242	        if (idempotencyKey != null) {
243	            idempotentCreates.put(idempotencyKey, owner.getId());
244	        }
245	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
246	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
247	            owner.getMembershipNumber());
248	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
249	        headers.setLocation(UriComponentsBuilder.newInstance()
250	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
251	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
252	    }
253	
254	    /**
255	     * Reads the client-supplied idempotency key from the current request's {@code Idempotency-Key}
256	     * header. Returns {@code null} when the header is absent or blank (the create is not idempotent),
257	     * or when no servlet request is bound to the current thread.
258	     *
259	     * @return the trimmed idempotency key, or {@code null} when none was supplied
260	     */
261	    private String currentIdempotencyKey() {
262	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
263	            String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
264	            if (StringUtils.hasText(key)) {
265	                return key.trim();
266	            }
267	        }
268	        return null;
269	    }
270	
271	    /**
272	     * Rejects a create whose supplied registration date is later than the server's current date. A
273	     * registration may be back-dated but never post-dated, so a future date is treated as a client
274	     * error. A {@code null} supplied date (the client omitted it) is allowed, as it defaults to the
275	     * server date.
276	     *
277	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when the
278	     *     client omitted it
279	     * @throws FutureRegistrationDateException if the supplied date is after the server's current date
280	     */
281	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
282	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
283	            throw new FutureRegistrationDateException(suppliedRegistrationDate);
284	        }
285	    }
286	
287	    /**
288	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
289	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
290	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
291	     * existed prior to this create.
292	     *
293	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
294	     *     a business day
295	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
296	     *     registered on that business day
297	     */
298	    private void requireDailyCapacity(LocalDate registrationDate) {
299	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
300	            throw new DailyOwnerLimitException(registrationDate);
301	        }
302	    }
303	
304	    /**
305	     * Counts the existing owners whose registration date equals the given business-day date. This is
306	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to
307	     * this create. It is the single definition of the per-day count shared by the daily-limit rule and
308	     * the bulk-signup warning.
309	     *
310	     * @param registrationDate the effective business-day registration date to count against
311	     * @return the number of pre-existing owners registered on that date
312	     */
313	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
314	        return this.clinicService.findAllOwners().stream()
315	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
316	            .count();
317	    }
318	
319	    /**
320	     * Rejects an owner whose city already contains the maximum allowed number of owners
321	     * ({@value #MAX_OWNERS_PER_CITY}). Existing owners are counted by city compared case-insensitively,
322	     * before the new owner is saved, so the count reflects only the owners that existed prior to this
323	     * create.
324	     *
325	     * @param city the city of the owner being created
326	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
327	     */
328	    private void requireCityHasCapacity(String city) {
329	        long cityOwnerCount = this.clinicService.findAllOwners().stream()
330	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
331	            .count();
332	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
333	            throw new CityOwnerLimitException(city);
334	        }
335	    }
336	
337	    /**
338	     * Validates a supplied postcode against the owner's region. Postcode is optional: an owner with no
339	     * postcode is accepted unchanged. When present it is a 4-digit string (enforced by the request
340	     * schema) that must fall within the inclusive range permitted for the region derived from the
341	     * owner's city ({@link #REGION_POSTCODE_RANGES}); a city whose region is unknown accepts any 4-digit
342	     * postcode. An out-of-range postcode is rejected with a 400 Bad Request.
343	     *
344	     * @param owner the owner being created, with its city and postcode set
345	     * @throws InvalidOwnerFieldsException if a supplied postcode is out of range for the city's region
346	     */
347	    private void validatePostcode(Owner owner) {
348	        String postcode = owner.getPostcode();
349	        if (postcode == null) {
350	            return;
351	        }
352	        int[] range = REGION_POSTCODE_RANGES.get(owner.getLocality());
353	        if (range == null) {
354	            return;
355	        }
356	        int value = Integer.parseInt(postcode);
357	        if (value < range[0] || value > range[1]) {
358	            throw new InvalidOwnerFieldsException(List.of("postcode"));
359	        }
360	    }
361	
362	    /**
363	     * Counts the existing owners that already share the given first name and last name, compared
364	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
365	     * owners that existed prior to this create.
366	     *
367	     * @param firstName the first name of the owner being created
368	     * @param lastName the last name of the owner being created
369	     * @return the number of pre-existing namesakes
370	     */
371	    private int countNamesakes(String firstName, String lastName) {
372	        return (int) this.clinicService.findAllOwners().stream()
373	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
374	                && equalsIgnoreCase(existing.getLastName(), lastName))
375	            .count();
376	    }
377	
378	    /**
379	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
380	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
381	     *
382	     * @param a the first value, possibly {@code null}
383	     * @param b the second value, possibly {@code null}
384	     * @return whether the values are equal ignoring case
385	     */
386	    private boolean equalsIgnoreCase(String a, String b) {
387	        return a == null ? b == null : a.equalsIgnoreCase(b);
388	    }
389	
390	    /**
391	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
392	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
393	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
394	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
395	     *
396	     * @param ownerFieldsDto the submitted owner fields
397	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
398	     */
399	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
400	        List<String> invalidFields = new ArrayList<>();
401	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
402	            invalidFields.add("firstName");
403	        }
404	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
405	            invalidFields.add("lastName");
406	        }
407	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddressLine1()))
408	            && !StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
409	            invalidFields.add("address");
410	        }
411	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
412	            invalidFields.add("city");
413	        }
414	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
415	            invalidFields.add("telephone");
416	        }
417	        if (!invalidFields.isEmpty()) {
418	            throw new InvalidOwnerFieldsException(invalidFields);
419	        }
420	    }
421	
422	    /**
423	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
424	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
425	     * what gets stored and returned.
426	     *
427	     * @param telephone the raw telephone value from the request
428	     * @return the normalized E.164 telephone number
429	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
430	     */
431	    private String normalizeTelephone(String telephone) {
432	        String e164 = toE164(telephone);
433	        if (e164 == null) {
434	            throw new InvalidOwnerFieldsException(List.of("telephone"));
435	        }
436	        return e164;
437	    }
438	
439	    /**
440	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
441	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
442	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
443	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
444	     * it contains 8 to 15 digits after the {@code '+'} and, for a recognized country code (see
445	     * {@link #NATIONAL_NUMBER_LENGTH}), carries exactly that country's required national-number length.
446	     *
447	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
448	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
449	     *
450	     * @param telephone the raw telephone value, possibly {@code null}
451	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
452	     */
453	    private String toE164(String telephone) {
454	        if (telephone == null) {
455	            return null;
456	        }
457	        String cleaned = telephone.replaceAll("[ \\-()]", "");
458	        String digits;
459	        if (cleaned.startsWith("+")) {
460	            digits = cleaned.substring(1);
461	        } else {
462	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
463	            digits = "61" + national;
464	        }
465	        if (!digits.matches("[0-9]{8,15}")) {
466	            return null;
467	        }
468	        if (!nationalNumberLengthValid(digits)) {
469	            return null;
470	        }
471	        return "+" + digits;
472	    }
473	
474	    /**
475	     * Checks a normalized E.164 digit string (country code followed by national digits, without the
476	     * leading {@code '+'}) against the per-country national-number length rule. For a country code
477	     * listed in {@link #NATIONAL_NUMBER_LENGTH} the national part must have exactly the required length
478	     * (e.g. {@code '+61'} needs 9 national digits, {@code '+1'} needs 10); any other country code is
479	     * accepted, leaving only the generic total-length rule to apply.
480	     *
481	     * @param digits the E.164 digits without the leading {@code '+'}
482	     * @return {@code true} if the national-number length matches the country code's requirement
483	     */
484	    private boolean nationalNumberLengthValid(String digits) {
485	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTH.entrySet()) {
486	            String code = entry.getKey();
487	            if (digits.startsWith(code)) {
488	                return digits.length() - code.length() == entry.getValue();
489	            }
490	        }
491	        return true;
492	    }
493	
494	    /**
495	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
496	     * {@code null}. When present, the value must be a syntactically valid address whose domain is not
497	     * on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); it is then stored and
498	     * returned lower-cased.
499	     *
500	     * @param email the raw email value from the request, possibly {@code null}
501	     * @return the lower-cased email, or {@code null} when none was supplied
502	     * @throws InvalidOwnerFieldsException if a value is present but is not a valid email address or
503	     *     its domain is on the disposable-domain blocklist
504	     */
505	    private String normalizeEmail(String email) {
506	        if (!StringUtils.hasText(email)) {
507	            return null;
508	        }
509	        String trimmed = email.trim();
510	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
511	            throw new InvalidOwnerFieldsException(List.of("email"));
512	        }
513	        String normalized = trimmed.toLowerCase(Locale.ROOT);
514	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
515	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
516	            throw new InvalidOwnerFieldsException(List.of("email"));
517	        }
518	        return normalized;
519	    }
520	
521	    /**
522	     * Rejects an owner whose whole identity key is already used by an existing owner. This is the
523	     * single consolidated duplicate check: the identity key ({@link Owner#getIdentityKey()}) is the
524	     * owner's normalized telephone, email (empty when absent) and household id joined with
525	     * {@code '|'}, and a create is a duplicate only when the new owner's whole key equals an existing
526	     * owner's. Because the telephone is part of the key, two members of the same household
527	     * (same {@code householdId}) with different telephones have different identity keys and are both
528	     * allowed.
529	     *
530	     * @param owner the owner being created, with its normalized telephone, email and household id set
531	     * @throws DuplicateIdentityException if another owner already has this identity key
532	     */
533	    private void requireUniqueIdentity(Owner owner) {
534	        String identityKey = owner.getIdentityKey();
535	        boolean inUse = this.clinicService.findAllOwners().stream()
536	            .filter(existing -> !existing.isDeleted())
537	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
538	        if (inUse) {
539	            throw new DuplicateIdentityException(identityKey);
540	        }
541	    }
542	
543	    /**
544	     * De-duplicates a newly computed customer code against the codes already held by existing owners.
545	     * When the computed code is unique it is returned unchanged. When it collides with an existing
546	     * owner's {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more
547	     * that makes the result unique (so a second collision yields {@code '-2'}, a third {@code '-3'}, and
548	     * so on), and that de-duplicated code is returned.
549	     *
550	     * @param customerCode the freshly computed customer code to de-duplicate
551	     * @return a customer code not held by any existing owner
552	     */
553	    private String deduplicateCustomerCode(String customerCode) {
554	        Set<String> inUse = this.clinicService.findAllOwners().stream()
555	            .map(Owner::getCustomerCode)
556	            .filter(Objects::nonNull)
557	            .collect(Collectors.toSet());
558	        if (!inUse.contains(customerCode)) {
559	            return customerCode;
560	        }
561	        int n = 2;
562	        String candidate;
563	        do {
564	            candidate = customerCode + "-" + n;
565	            n++;
566	        } while (inUse.contains(candidate));
567	        return candidate;
568	    }
569	
570	    /**
571	     * Flags the owner being created as a possible (soft) duplicate of an existing owner. A soft match is
572	     * not a hard duplicate (its identity key is unique, already enforced by {@link #requireUniqueIdentity})
573	     * but it shares an existing owner's last name (compared case-insensitively) and postcode (both
574	     * present and equal) while carrying a different normalized telephone. When such an existing owner is
575	     * found the created owner is flagged ({@code possibleDuplicate} true) with {@code possibleDuplicateOf}
576	     * set to that owner's id; the lowest matching id is used when several owners match. Otherwise the flag
577	     * is false and {@code possibleDuplicateOf} is left unset.
578	     *
579	     * <p>A declared household member (one created with {@code sharesHousehold}) is never a suspected
580	     * duplicate: it has deliberately opted in to sharing its household, so the flag is forced false.
581	     *
582	     * @param owner the owner being created, with its normalized telephone and postcode set
583	     * @param declaredHouseholdMember whether the owner opted in to its household via {@code sharesHousehold}
584	     */
585	    private void flagPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
586	        if (declaredHouseholdMember || owner.getPostcode() == null) {
587	            owner.setPossibleDuplicate(false);
588	            return;
589	        }
590	        Integer matchId = this.clinicService.findAllOwners().stream()
591	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
592	                && owner.getPostcode().equals(existing.getPostcode())
593	                && !owner.getTelephone().equals(existing.getTelephone()))
594	            .map(Owner::getId)
595	            .min(Integer::compareTo)
596	            .orElse(null);
597	        owner.setPossibleDuplicate(matchId != null);
598	        owner.setPossibleDuplicateOf(matchId);
599	    }
600	
601	    /**
602	     * Rejects a create that would join an existing household unless it has opted in via
603	     * {@code sharesHousehold}. The household is keyed on the deterministic {@code householdId} (derived
604	     * from the normalized last name and postcode; see {@link #computeHouseholdId}), so any existing
605	     * owner carrying the same {@code householdId} is a member of the same household. When one exists and
606	     * the create has not declared household membership, the second owner is a household duplicate.
607	     *
608	     * <p>A create that declares {@code sharesHousehold} bypasses this block entirely and is created as a
609	     * declared household member.
610	     *
611	     * @param owner the owner being created, with its deterministic {@code householdId} already set
612	     * @param declaredHouseholdMember whether the owner opted in to its household via {@code sharesHousehold}
613	     * @throws DuplicateHouseholdException if an existing owner already shares the household and the
614	     *     create did not declare {@code sharesHousehold}
615	     */
616	    private void requireNoHouseholdDuplicate(Owner owner, boolean declaredHouseholdMember) {
617	        if (declaredHouseholdMember) {
618	            return;
619	        }
620	        String householdId = owner.getHouseholdId();
621	        boolean inUse = this.clinicService.findAllOwners().stream()
622	            .filter(existing -> !existing.isDeleted())
623	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
624	        if (inUse) {
625	            throw new DuplicateHouseholdException(householdId);
626	        }
627	    }
628	
629	    /**
630	     * Stamps the household's member count after this create ({@code householdSize}) onto every member of
631	     * the household - the existing owners that share the deterministic {@code householdId} and the new
632	     * one - so the shared size can be read back from any of them. The count is the number of existing
633	     * members plus the owner being created.
634	     *
635	     * @param owner the owner being created, with its deterministic {@code householdId} already set
636	     */
637	    private void stampHouseholdSize(Owner owner) {
638	        String householdId = owner.getHouseholdId();
639	        List<Owner> members = this.clinicService.findAllOwners().stream()
640	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
641	            .toList();
642	        int householdSize = members.size() + 1;
643	        owner.setHouseholdSize(householdSize);
644	        for (Owner member : members) {
645	            member.setHouseholdSize(householdSize);
646	            this.clinicService.saveOwner(member);
647	        }
648	    }
649	
650	    /**
651	     * Computes the deterministic, shared household identifier for a last name and postcode: the first
652	     * 12 upper-case hexadecimal characters (the first 6 bytes) of the SHA-256 digest of
653	     * {@code normalizedLastName + '|' + postcode}. The last name is normalized (case-insensitive,
654	     * whitespace-collapsed) and an absent postcode contributes an empty string, so every owner that
655	     * shares a last name and postcode computes the same identifier and therefore the same household.
656	     *
657	     * @param lastName the last name of the household
658	     * @param postcode the postcode of the household, possibly {@code null}
659	     * @return the 12-character upper-case hex household identifier
660	     */
661	    private String computeHouseholdId(String lastName, String postcode) {
662	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
663	        try {
664	            byte[] digest = MessageDigest.getInstance("SHA-256")
665	                .digest(key.getBytes(StandardCharsets.UTF_8));
666	            StringBuilder hex = new StringBuilder(12);
667	            for (int i = 0; i < 6; i++) {
668	                hex.append(String.format("%02X", digest[i]));
669	            }
670	            return hex.toString();
671	        } catch (NoSuchAlgorithmException e) {
672	            throw new IllegalStateException("SHA-256 algorithm not available", e);
673	        }
674	    }
675	
676	    /**
677	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
678	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
679	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
680	     *
681	     * @param value the raw value, possibly {@code null}
682	     * @return the normalized value
683	     */
684	    private String normalizeForHousehold(String value) {
685	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
686	    }
687	
688	    /**
689	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
690	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
691	     * value yields an empty string.
692	     *
693	     * @param value the raw value, possibly {@code null}
694	     * @return the trimmed, whitespace-collapsed value
695	     */
696	    private String collapseWhitespace(String value) {
697	        if (value == null) {
698	            return "";
699	        }
700	        return value.trim().replaceAll("\\s+", " ");
701	    }
702	
703	    /**
704	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
705	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
706	     * is upper-cased, and common street-type abbreviations are expanded as whole words
707	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
708	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
709	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
710	     *
711	     * @param address the raw address value, possibly {@code null}
712	     * @return the normalized address
713	     */
714	    private String normalizeAddress(String address) {
715	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
716	        if (collapsed.isEmpty()) {
717	            return "";
718	        }
719	        String[] tokens = collapsed.split(" ");
720	        StringBuilder normalized = new StringBuilder();
721	        for (int i = 0; i < tokens.length; i++) {
722	            if (i > 0) {
723	                normalized.append(' ');
724	            }
725	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
726	        }
727	        return normalized.toString();
728	    }
729	
730	    /**
731	     * Applies the owner's address from the request, preferring the structured form over the flat one.
732	     * When a non-blank {@code addressLine1} is supplied it is normalized ({@link #normalizeAddress}) and
733	     * stored, along with the normalized {@code addressLine2} when present, and the stored {@code address}
734	     * is the composed string ({@link #composeAddress}). Otherwise the flat {@code address} input is
735	     * normalized and stored, and the structured lines are cleared. Normalization therefore applies to
736	     * whichever address fields are supplied, and everything that reads {@link Owner#getAddress()} sees
737	     * the structured address when present, falling back to the flat address.
738	     *
739	     * @param owner the owner being created
740	     * @param ownerFieldsDto the submitted owner fields
741	     */
742	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
743	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
744	        if (StringUtils.hasText(line1)) {
745	            String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
746	            String normalizedLine2 = StringUtils.hasText(line2) ? line2 : null;
747	            owner.setAddressLine1(line1);
748	            owner.setAddressLine2(normalizedLine2);
749	            owner.setAddress(composeAddress(line1, normalizedLine2));
750	        } else {
751	            owner.setAddressLine1(null);
752	            owner.setAddressLine2(null);
753	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
754	        }
755	    }
756	
757	    /**
758	     * Composes the stored-and-returned {@code address} string from the normalized structured lines: the
759	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
760	     * appended when the second line is present.
761	     *
762	     * @param line1 the normalized first address line
763	     * @param line2 the normalized second address line, or {@code null} when absent
764	     * @return the composed address string
765	     */
766	    private String composeAddress(String line1, String line2) {
767	        return line2 == null ? line1 : line1 + " " + line2;
768	    }
769	
770	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
771	    @Override
772	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
773	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
774	        if (currentOwner == null) {
775	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
776	        }
777	        currentOwner.setAddress(ownerFieldsDto.getAddress());
778	        currentOwner.setCity(ownerFieldsDto.getCity());
779	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
780	        currentOwner.setLastName(ownerFieldsDto.getLastName());
781	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
782	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
783	        this.clinicService.saveOwner(currentOwner);
784	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
785	    }
786	
787	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
788	    @Transactional
789	    @Override
790	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
791	        Owner owner = this.clinicService.findOwnerById(ownerId);
792	        if (owner == null) {
793	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
794	        }
795	        owner.setDeleted(true);
796	        this.clinicService.saveOwner(owner);
797	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
798	    }
799	
800	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
801	    @Override
802	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
803	        Owner owner = this.clinicService.findOwnerById(ownerId);
804	        if (owner == null) {
805	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
806	        }
807	        HttpHeaders headers = new HttpHeaders();
808	        Pet pet = petMapper.toPet(petFieldsDto);
809	        owner.setId(ownerId);
810	        pet.setOwner(owner);
811	        pet.getType().setName(null);
812	        this.clinicService.savePet(pet);
813	        PetDto petDto = petMapper.toPetDto(pet);
814	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
815	            .buildAndExpand(pet.getId()).toUri());
816	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
817	    }
818	
819	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
820	    @Override
821	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
822	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
823	        if (currentOwner != null) {
824	            Pet currentPet = this.clinicService.findPetById(petId);
825	            if (currentPet != null) {
826	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
827	                currentPet.setName(petFieldsDto.getName());
828	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
829	                this.clinicService.savePet(currentPet);
830	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
831	            }
832	        }
833	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
834	    }
835	
836	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
837	    @Override
838	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
839	        HttpHeaders headers = new HttpHeaders();
840	        Visit visit = visitMapper.toVisit(visitFieldsDto);
841	        Pet pet = new Pet();
842	        pet.setId(petId);
843	        visit.setPet(pet);
844	        this.clinicService.saveVisit(visit);
845	        VisitDto visitDto = visitMapper.toVisitDto(visit);
846	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
847	            .buildAndExpand(visit.getId()).toUri());
848	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
849	    }
850	
851	
852	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
853	    @Override
854	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
855	        Owner owner = this.clinicService.findOwnerById(ownerId);
856	        if (owner != null) {
857	            Pet pet = owner.getPet(petId);
858	            if (pet != null) {
859	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
860	            }
861	        }
862	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
863	    }
864	}
